#include <stdio.h>

int main() {
    int a = 10, b = 3;
    int sum, diff, prod, quot, rem;
    int x = 5;

    /* Arithmetic Operators */
    sum  = a + b;
    diff = a - b;
    prod = a * b;
    quot = a / b;
    rem  = a % b;

    printf("a = %d, b = %d\n", a, b);
    printf("Sum      : %d\n", sum);
    printf("Difference: %d\n", diff);
    printf("Product  : %d\n", prod);
    printf("Quotient : %d\n", quot);
    printf("Remainder: %d\n", rem);

    /* Relational Operators */
    printf("\nRelational Operators:\n");
    printf("a > b  : %d\n", a > b);
    printf("a == b : %d\n", a == b);
    printf("a != b : %d\n", a != b);

    /* Logical Operators */
    printf("\nLogical Operators:\n");
    printf("(a>5)&&(b<5): %d\n", (a > 5) && (b < 5));
    printf("(a<5)||(b<5): %d\n", (a < 5) || (b < 5));

    /* Increment and Decrement */
    printf("\nIncrement/Decrement:\n");
    printf("x = %d\n", x);
    printf("x++ gives: %d (then x=%d)\n", x++, x);
    x = 5; /* reset */
    printf("++x gives: %d\n", ++x);

    /* Compound Assignment */
    printf("\nCompound Assignment:\n");
    a += 5;
    printf("a += 5 => a = %d\n", a);
    a -= 3;
    printf("a -= 3 => a = %d\n", a);

    return 0;
}

