#include <stdio.h>

int main() {
    int i;

    /* 1. for loop: print 1 to 5 */
    printf("for loop:\n");
    for (i = 1; i <= 5; i++) {
        printf("%d ", i);
    }
    printf("\n");

    /* 2. while loop: print 1 to 5 */
    printf("while loop:\n");
    i = 1;
    while (i <= 5) {
        printf("%d ", i);
        i++;
    }
    printf("\n");

    /* 3. do-while loop: print 1 to 5 */
    printf("do-while loop:\n");
    i = 1;
    do {
        printf("%d ", i);
        i++;
    } while (i <= 5);
    printf("\n");

    /* 4. break and continue demo */
    printf("skip 3, stop at 7:\n");
    for (i = 1; i <= 10; i++) {
        if (i == 3) continue; /* skip 3 */
        if (i == 7) break;    /* stop at 7 */
        printf("%d ", i);
    }
    printf("\n");

    return 0;
}

