public class OperatorsDemo {
    public static void main(String[] args) {

        // 1. Arithmetic Operators
        int a = 15, b = 4;
        System.out.println("a + b = " + (a + b));   // 19
        System.out.println("a - b = " + (a - b));   // 11
        System.out.println("a * b = " + (a * b));   // 60
        System.out.println("a / b = " + (a / b));   // 3 (integer division)
        System.out.println("a % b = " + (a % b));   // 3 (remainder)

        // 2. Relational Operators
        System.out.println("a == b: " + (a == b));  // false
        System.out.println("a > b:  " + (a > b));   // true
        System.out.println("a <= b: " + (a <= b));  // false

        // 3. Logical Operators
        boolean x = true, y = false;
        System.out.println("x && y: " + (x && y));  // false
        System.out.println("x || y: " + (x || y));  // true
        System.out.println("!x:     " + (!x));       // false

        // 4. Assignment & Compound Assignment
        int c = 10;
        c += 5;   // c = c + 5
        System.out.println("c after += 5: " + c);   // 15
        c *= 2;   // c = c * 2
        System.out.println("c after *= 2: " + c);   // 30

        // 5. Increment / Decrement
        int n = 5;
        System.out.println("n++: " + n++); // prints 5, then n becomes 6
        System.out.println("n after post-increment: " + n); // 6
        System.out.println("++n: " + (++n)); // n becomes 7, prints 7

        // 6. Ternary Operator
        int marks = 55;
        String result = (marks >= 50) ? "Pass" : "Fail";
        System.out.println("Result: " + result);     // Pass
    }
}

