public class StringDemo {
    public static void main(String[] args) {

        // Creating strings
        String firstName = "Riya";
        String lastName  = new String("Sharma");

        // Concatenation
        String fullName = firstName + " " + lastName;
        System.out.println("Full Name: " + fullName);

        // length()
        System.out.println("Length: " + fullName.length());

        // charAt()
        System.out.println("First char: " + fullName.charAt(0));

        // substring()
        System.out.println("First name only: " + fullName.substring(0, 4));

        // toUpperCase() and toLowerCase()
        System.out.println("Upper: " + fullName.toUpperCase());
        System.out.println("Lower: " + fullName.toLowerCase());

        // trim()
        String messy = "  Hello  ";
        System.out.println("Trimmed: '" + messy.trim() + "'");

        // equals() vs ==
        String a = "Java";
        String b = "Java";
        String c = new String("Java");
        System.out.println("a.equals(b): " + a.equals(b));   // true
        System.out.println("a == b: "      + (a == b));        // true (same pool object)
        System.out.println("a == c: "      + (a == c));        // false (different object)
        System.out.println("a.equals(c): " + a.equals(c));    // true

        // contains()
        System.out.println("Contains 'Riya': " + fullName.contains("Riya"));
    }
}

